package nl.smartstreamlabs.sbwdroneconfig;
import com.google.gson.*;import java.util.*;import java.io.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import org.joml.Matrix4d;import org.joml.Vector3d;
/** Original Free Model coordinates and hierarchy; immutable geometry is shared by server and renderer. */
public final class Fl01Geometry{
 public static final Fl01Geometry MISSILE=new Fl01Geometry("missile"),PLATFORM=new Fl01Geometry("platform");
 public record Bone(String name,int parent,Vector3d pivot,Vector3d rotation,JsonObject tracks){}
 public final String key;public final List<Bone>bones=new ArrayList<>();public final int[][]cells,support;public final AABB bounds;private final List<AABB>boxes=new ArrayList<>();private final Map<Direction,VoxelShape[]>shapes=new EnumMap<>(Direction.class);
 private Fl01Geometry(String key){this.key=key;try(var r=new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/fl01/"+key+".json")),java.nio.charset.StandardCharsets.UTF_8)){var j=JsonParser.parseReader(r).getAsJsonObject();for(var v:j.getAsJsonArray("bones")){var b=v.getAsJsonObject();bones.add(new Bone(b.get("name").getAsString(),b.get("parent").getAsInt(),vec(b.getAsJsonArray("pivot")),vec(b.getAsJsonArray("rotation")),b.getAsJsonObject("tracks")));}cells=new Gson().fromJson(j.get("cells"),int[][].class);support=new Gson().fromJson(j.get("support"),int[][].class);bounds=box(j.getAsJsonArray("bounds"));for(var pose:j.getAsJsonArray("poses"))for(var b:pose.getAsJsonArray())boxes.add(box(b.getAsJsonArray()));}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 private static Vector3d vec(JsonArray a){return new Vector3d(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}private static AABB box(JsonArray a){return new AABB(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),a.get(3).getAsDouble(),a.get(4).getAsDouble(),a.get(5).getAsDouble());}
 private static Vector3d sample(Bone b,String channel,double t,Vector3d fallback){if(!b.tracks.has(channel))return fallback;JsonArray last=null;for(var value:b.tracks.getAsJsonArray(channel)){var k=value.getAsJsonArray();double at=k.get(0).getAsDouble();if(t<=at){if(last==null)return vec(k.get(1).getAsJsonArray());double prev=last.get(0).getAsDouble();return vec(last.get(1).getAsJsonArray()).lerp(vec(k.get(1).getAsJsonArray()),Math.max(0,Math.min(1,(t-prev)/Math.max(.00001,at-prev))));}last=k;}return vec(last.get(1).getAsJsonArray());}
 public Matrix4d[]transforms(double time){var out=new Matrix4d[bones.size()];for(int i=0;i<out.length;i++){var b=bones.get(i);var r=new Vector3d(b.rotation).add(sample(b,"rotation",time,new Vector3d()));var s=sample(b,"scale",time,new Vector3d(1));out[i]=new Matrix4d(b.parent<0?new Matrix4d():out[b.parent]).translate(b.pivot).rotateZYX(Math.toRadians(r.z),Math.toRadians(r.y),Math.toRadians(r.x)).scale(s).translate(-b.pivot.x,-b.pivot.y,-b.pivot.z);}return out;}
 public static Matrix4d world(BlockPos p,Direction f){return new Matrix4d().translation(p.getX()+.5,p.getY(),p.getZ()+.5).rotateY(Math.toRadians(180-f.toYRot()));}
 public static Matrix4d dock(BlockPos p,Direction f,double time){return world(p,f).translate(0,1.3,3.5).rotateX(Math.toRadians(rail(time))).translate(0,-1.3,-3.5).translate(0,2.66,-.8);}
 public static final double[][] AIRFRAME={{-.7,-.7,-7.05,.7,.7,5.66},{-3.32,-.08,-1.2,3.32,.08,1.2},{-.5,.7,.5,.5,1.706,5.5}};
 public static AABB partBounds(double[] part){return new AABB(part[0],part[1],part[2],part[3],part[4],part[5]);}
 public static com.atsuishio.superbwarfare.tools.OBB partBox(Matrix4d frame,double[] part){var center=frame.transformPosition(new Vector3d((part[0]+part[3])/2,(part[1]+part[4])/2,(part[2]+part[5])/2));return new com.atsuishio.superbwarfare.tools.OBB(center,new Vector3d((part[3]-part[0])/2,(part[4]-part[1])/2,(part[5]-part[2])/2),frame.getNormalizedRotation(new org.joml.Quaterniond()),com.atsuishio.superbwarfare.tools.OBB.Part.BODY);}
 public static double rail(double t){if(t<=1.5)return 25-15*Math.max(0,t)/1.5;if(t<=3.5)return 10+25*(t-1.5)/2;return 35-10*Math.min(1,(t-3.5)/2.5);}
 public static Vec3 point(Matrix4d m,Vec3 p){var v=m.transformPosition(new Vector3d(p.x,p.y,p.z));return new Vec3(v.x,v.y,v.z);}
 public static Matrix4d frame(Fl01Entity e,float p){return new Matrix4d().translation(net.minecraft.util.Mth.lerp(p,e.xo,e.getX()),net.minecraft.util.Mth.lerp(p,e.yo,e.getY()),net.minecraft.util.Mth.lerp(p,e.zo,e.getZ())).rotateY(Math.toRadians(180-net.minecraft.util.Mth.rotLerp(p,e.yRotO,e.getYRot()))).rotateX(Math.toRadians(-net.minecraft.util.Mth.lerp(p,e.xRotO,e.getXRot())));}
 public BlockPos cell(BlockPos p,Direction f,int i){int[]c=cells[i];return offset(p,f,c);}public static BlockPos offset(BlockPos p,Direction f,int[]c){var v=point(world(BlockPos.ZERO,f),new Vec3(c[0],c[1],c[2]));return p.offset((int)Math.round(v.x-.5),c[1],(int)Math.round(v.z-.5));}public BlockPos root(BlockPos p,Direction f,int i){return p.subtract(cell(BlockPos.ZERO,f,i));}
 public static AABB transform(Matrix4d m,AABB b){AABB all=null;for(int i=0;i<8;i++){var p=point(m,new Vec3((i&1)==0?b.minX:b.maxX,(i&2)==0?b.minY:b.maxY,(i&4)==0?b.minZ:b.maxZ));var c=new AABB(p,p);all=all==null?c:all.minmax(c);}return all;}
 public synchronized VoxelShape shape(Direction f,int part){var cached=shapes.get(f);if(cached==null){cached=new VoxelShape[cells.length];var m=world(BlockPos.ZERO,f);var transformed=boxes.stream().map(b->transform(m,b)).toList();for(int i=0;i<cells.length;i++){var at=cell(BlockPos.ZERO,f,i);var s=Shapes.empty();for(var b:transformed){double x0=Math.max(0,b.minX-at.getX()),y0=Math.max(0,b.minY-at.getY()),z0=Math.max(0,b.minZ-at.getZ()),x1=Math.min(1,b.maxX-at.getX()),y1=Math.min(1,b.maxY-at.getY()),z1=Math.min(1,b.maxZ-at.getZ());if(x1>x0&&y1>y0&&z1>z0)s=Shapes.or(s,Shapes.box(x0,y0,z0,x1,y1,z1));}cached[i]=s.optimize();}shapes.put(f,cached);}return part>=0&&part<cached.length?cached[part]:Shapes.empty();}
}
